typedef enum {
    Z_IOERROR_TAG_NOTFOUND,
    Z_IOERROR_TAG_PERMISSIONDENIED,
    Z_IOERROR_TAG_INTERRUPTED,
    Z_IOERROR_TAG_INVALIDPATH,
    Z_IOERROR_TAG_EOF,
    Z_IOERROR_TAG_BADENCODING,
    Z_IOERROR_TAG_EXISTS,
    Z_IOERROR_TAG_ISDIR,
    Z_IOERROR_TAG_NOTDIR,
    Z_IOERROR_TAG_NOSPACE,
    Z_IOERROR_TAG_OTHER,
} z_t2366_tag_t;
struct z_t2366_t {
    uint8_t tag;
    void* data;
};
static void z_t2366_destroy(z_t2366_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_IOERROR_TAG_INVALIDPATH:
            z_t57_free((z_t57_t*)u->data);
            free(u->data);
            break;
        case Z_IOERROR_TAG_OTHER:
            z_t57_free((z_t57_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

